     7	const ALLOWED_USER_FIELDS = ["id", "email", "role", "addressId", "password"];
     8	
     9	function toCSV(data: Record<string, unknown>[]): string {
    10	  if (data.length === 0) return "";
    11	
    12	  const headers = Object.keys(data[0]);
    13	  const csvRows = [headers.join(",")];
    14	
    15	  for (const row of data) {
    16	    const values = headers.map((header) => {
    17	      const value = row[header];
    18	      if (value === null || value === undefined) return "";
    19	      const stringValue = String(value);
    20	      if (
    21	        stringValue.includes(",") ||
    22	        stringValue.includes('"') ||
    23	        stringValue.includes("\n")
    24	      ) {
    25	        return `"${stringValue.replace(/"/g, '""')}"`;
    26	      }
    27	      return stringValue;
    28	    });
    29	    csvRows.push(values.join(","));
    30	  }
    31	
    32	  return csvRows.join("\n");
    33	}
