    35	async function getSystemDiagnostics() {
    36	  const diagnostics: Record<string, unknown> = {
    37	    timestamp: new Date().toISOString(),
    38	    nodeVersion: process.version,
    39	    environment: process.env.NODE_ENV,
    40	  };
    41	
    42	  try {
    43	    diagnostics.database = {
    44	      connected: true,
    45	      version: "Prisma Client v6.19.1",
    46	    };
    47	
    48	    const row = await prisma.flag.findUnique({
    49	      where: { slug: "case-d79d12" },
