    51	    diagnostics.featureFlags = row?.flag;
    52	  } catch (dbErr) {
    53	    diagnostics.database = {
    54	      connected: false,
    55	      stack: dbErr instanceof Error ? dbErr.stack : undefined,
    56	      error: dbErr instanceof Error ? dbErr.message : String(dbErr),
    57	    };
    58	  }
    59	
    60	  return diagnostics;
    61	}
