    67	    const { format, fields } = parsed.data;
    68	
    69	    const requestedFields = fields
    70	      .map((f) => String(f).trim())
    71	      .filter((f) => f.length > 0);
    72	
    73	    const invalidFields = requestedFields.filter(
    74	      (f: string) => !ALLOWED_USER_FIELDS.includes(f)
    75	    );
    76	
    77	    if (invalidFields.length > 0) {
    78	      const diagnostics = await getSystemDiagnostics();
    79	
    80	      return NextResponse.json(
