    83	          invalidFields: invalidFields,
    84	          allowedFields: ALLOWED_USER_FIELDS,
    85	          debug: {
    86	            message: "Export failed due to invalid field specification",
    87	            requestedFields: requestedFields,
    88	            systemDiagnostics: diagnostics,
    89	          },
    90	        },
    91	        { status: 400 }
    92	      );
    93	    }
    94	
