    10	  if (!parsed.success) return parsed.response;
    11	  const { token } = parsed.data;
    12	
    13	  let resourcePath: string;
    14	  try {
    15	    resourcePath = decryptShareToken(token);
    16	  } catch {
    17	    return NextResponse.json(
    18	      { error: "Invalid share token format" },
    19	      { status: 400 }
    20	    );
    21	  }
    22	
    23	  const colonIndex = resourcePath.indexOf(":");
    24	  if (colonIndex === -1) {
    25	    return NextResponse.json(
    26	      { error: "Shared resource not found" },
    27	      { status: 404 }
    28	    );
    29	  }
    30	
    31	  const resourceType = resourcePath.substring(0, colonIndex);
    32	  const resourceId = resourcePath.substring(colonIndex + 1);
    33	
    34	  const supportedTypes = ["order", "report"];
    35	  if (!supportedTypes.includes(resourceType)) {
    36	    return NextResponse.json(
