    59	        { status: 404 }
    60	      );
    61	    }
    62	
    63	    const emailName = order.user.email.split("@")[0];
    64	    const customerName = emailName.charAt(0).toUpperCase() + emailName.slice(1);
    65	
    66	    return NextResponse.json({
    67	      type: "order",
    68	      order: {
