lib/share-crypto.ts
     1	import crypto from "crypto";
     2	
     3	const ALGORITHM = "aes-256-cbc";
     4	const IV_LENGTH = 16;
     5	
     6	const SHARE_KEY = Buffer.from(
     7	  process.env.SHARE_ENCRYPTION_KEY ||
     8	    "a1b2c3d4e5f6a7b8c9d0e1f2a3b4c5d6e7f8a9b0c1d2e3f4a5b6c7d8e9f0a1b2",
     9	  "hex"
    10	);
    11	
    12	export function encryptShareToken(plaintext: string): string {
    13	  const iv = crypto.randomBytes(IV_LENGTH);
    14	  const cipher = crypto.createCipheriv(ALGORITHM, SHARE_KEY, iv);
    15	  const encrypted = Buffer.concat([
    16	    cipher.update(plaintext, "utf8"),
    17	    cipher.final(),
    18	  ]);
    19	  return Buffer.concat([iv, encrypted]).toString("hex");
    20	}
    21	
    22	export function decryptShareToken(tokenHex: string): string {
    23	  const data = Buffer.from(tokenHex, "hex");
    24	  const iv = data.subarray(0, IV_LENGTH);
    25	  const ciphertext = data.subarray(IV_LENGTH);
    26	  const decipher = crypto.createDecipheriv(ALGORITHM, SHARE_KEY, iv);
    27	  const decrypted = Buffer.concat([
    28	    decipher.update(ciphertext),
    29	    decipher.final(),
    30	  ]);
    31	  return decrypted.toString("utf8");
    32	}

