     5	
     6	const MIME_TYPES: Record<string, string> = {
     7	  ".jpg": "image/jpeg",
     8	  ".jpeg": "image/jpeg",
     9	  ".png": "image/png",
    10	  ".gif": "image/gif",
    11	  ".webp": "image/webp",
    12	  ".svg": "image/svg+xml",
    13	};
    14	
    15	export async function GET(
    16	  _request: NextRequest,
    17	  { params }: { params: Promise<{ path: string[] }> }
    18	) {
    19	  const { path } = await params;
    20	  const filename = path.join("/");
    21	
    22	  if (filename.includes("..") || filename.includes("\0")) {
    23	    return NextResponse.json({ error: "Invalid path" }, { status: 400 });
    24	  }
    25	
    26	  const filepath = join(process.cwd(), "uploads", filename);
    27	
    28	  if (!existsSync(filepath)) {
    29	    return NextResponse.json({ error: "File not found" }, { status: 404 });
    30	  }
    31	
    32	  const ext = filename.substring(filename.lastIndexOf(".")).toLowerCase();
    33	  const contentType = MIME_TYPES[ext];
    34	
    35	  if (!contentType) {
    36	    return NextResponse.json(
    37	      { error: "Unsupported file type" },
    38	      { status: 400 }
    39	    );
    40	  }
    41	
    42	  const fileBuffer = await readFile(filepath);
    43	
    44	  return new NextResponse(fileBuffer, {
    45	    headers: {
    46	      "Content-Type": contentType,
    47	      "Cache-Control": "public, max-age=31536000, immutable",
    48	    },
    49	  });
    50	}

