     5	import { parseQuery } from "@/lib/validation";
     6	import { filesQuerySchema } from "@/lib/validation/schemas/files";
     8	export async function GET(request: NextRequest) {
     9	  try {
    10	    const { searchParams } = new URL(request.url);
    11	    const parsed = parseQuery(searchParams, filesQuerySchema);
    12	    if (!parsed.success) return parsed.response;
    13	    const file = parsed.data.file ?? null;
    14	    const listDir = parsed.data.list ?? null;
    15	    const dirPath = parsed.data.path ?? "";
    17	    const baseDir = join(process.cwd(), "documents");
    19	    if (listDir === "true") {
    20	      const targetDir = join(baseDir, dirPath);
    21	      const entries = await readdir(targetDir, { withFileTypes: true });
    23	      const items = await Promise.all(
    24	        entries.map(async (entry) => {
    25	          const fullPath = join(targetDir, entry.name);
    26	          const stats = await stat(fullPath);
    27	          return {
    28	            name: entry.name,
    29	            type: entry.isDirectory() ? "directory" : "file",
    30	            size: stats.size,
    31	            modified: stats.mtime.toISOString(),
    32	          };
    33	        })
    34	      );
    36	      return NextResponse.json({
    37	        path: dirPath,
    38	        items,
    39	      });
    40	    }
    42	    if (!file) {
    43	      return NextResponse.json(
    44	        { error: "File parameter is required" },
    45	        { status: 400 }
    46	      );
    47	    }
    49	    const filePath = join(baseDir, file);
    50	    const extension = extname(file).toLowerCase();
    52	    if (extension === ".pdf") {
    53	      const content = await readFile(filePath);
    54	      return new NextResponse(content, {
    55	        headers: {
    56	          "Content-Type": "application/pdf",
    57	          "Content-Disposition": `inline; filename="${file.split("/").pop()}"`,
    58	        },
    59	      });
    60	    }
    62	    const content = await readFile(filePath, "utf-8");
    64	    return NextResponse.json({
    65	      filename: file,
    66	      content,
    67	    });
    68	  } catch (error) {
    69	    logger.error({ err: error, route: "/api/files" }, "Error reading file");
    70	    return NextResponse.json({ error: "Failed to read file" }, { status: 500 });
    71	  }
    72	}

