let p=JSON.parse(load("npmprod").split("\nnpm notice")[0]);
const out=JSON.stringify(p,null,2);
let a=await tools.apply_patch("*** Begin Patch\n*** Add File: .security-audit-npm-cache/prod.json\n"+out.split("\n").map(s=>"+"+s).join("\n")+"\n*** End Patch");
text(a);
text(await tools.exec_command({cmd:`node <<'NODE'
const fs = require('node:fs');
const production = JSON.parse(fs.readFileSync('.security-audit-npm-cache/prod.json', 'utf8'));
const full = JSON.parse(fs.readFileSync('.security-audit-npm-cache/all.json', 'utf8'));
const metadata = {
  fecha: '2026-11-24',
  registro: 'https://registry.npmjs.org/',
  npm: '9.8.0',
  lockfile: 'package-lock.json',
  sha256: require('node:crypto').createHash('sha256').update(fs.readFileSync('package-lock.json')).digest('hex'),
};
fs.writeFileSync('AUDITORIA_DEPENDENCIAS_NPM.json', JSON.stringify({
  metadata,
  produccion: { comando: 'npm audit --omit=dev --ignore-scripts --json', resultado: production },
  completo: { comando: 'npm audit --ignore-scripts --json', resultado: full },
}, null, 2) + '\\n', { flag: 'wx' });
console.log(JSON.stringify({ produccion: production.metadata.vulnerabilities, completo: full.metadata.vulnerabilities }));
NODE`}));

